      "code": "def build(p):\n    import math\n    body = cq.Workplane('XY').circle(p.outer_d / 2).extrude(p.thickness)\n    # Six vertical finger scallops provide grip while keeping the knob about 30 mm across.\n    for i in range(6):\n        a = math.radians(60 * i)\n        x = p.grip_flute_center_r * math.cos(a)\n        y = p.grip_flute_center_r * math.sin(a)\n        flute = cq.Workplane('XY').center(x, y).circle(p.grip_flute_r).extrude(p.thickness)\n        body = body.cut(flute)\n    def hex_points(af):\n        radius = af / math.sqrt(3.0)\n        return [(radius * math.cos(math.radians(30 + 60 * i)),\n                 radius * math.sin(math.radians(30 + 60 * i))) for i in range(6)]\n    pocket = cq.Workplane('XY').polyline(hex_points(p.nut_pocket_af)).close().extrude(p.pocket_depth)\n    lead = (cq.Workplane('XY')\n            .polyline(hex_points(p.entry_af)).close()\n            .workplane(offset=p.entry_depth)\n            .polyline(hex_points(p.nut_pocket_af)).close()\n            .loft(combine=True))\n    body = body.cut(pocket).cut(lead)\n    # The nut's threaded hole opens into this continuous bolt passage.\n    passage = cq.Workplane('XY').circle(p.bolt_clear_d / 2).extrude(p.thickness)\n    return body.cut(passage)",
